-- ATTOZAP DISPAROS initial production schema.
-- This migration is written for PostgreSQL-compatible Prisma deployments.
CREATE TABLE IF NOT EXISTS "Company" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'active', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "User" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "name" TEXT NOT NULL, "email" TEXT NOT NULL, "role" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "WhatsAppConnection" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "name" TEXT NOT NULL, "phoneNumber" TEXT NOT NULL, "status" TEXT NOT NULL, "qrCode" TEXT, "connectedAt" TIMESTAMP, "lastHeartbeatAt" TIMESTAMP, "messagesSent" INTEGER NOT NULL DEFAULT 0, "totalFailures" INTEGER NOT NULL DEFAULT 0, "dailyLimit" INTEGER NOT NULL DEFAULT 500, "hourlyLimit" INTEGER NOT NULL DEFAULT 60, "delayMinMs" INTEGER NOT NULL DEFAULT 12000, "delayMaxMs" INTEGER NOT NULL DEFAULT 45000, "sessionPath" TEXT NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ContactList" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "name" TEXT NOT NULL, "source" TEXT NOT NULL, "totalContacts" INTEGER NOT NULL DEFAULT 0, "validContacts" INTEGER NOT NULL DEFAULT 0, "invalidContacts" INTEGER NOT NULL DEFAULT 0, "duplicateContacts" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Contact" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "contactListId" TEXT NOT NULL REFERENCES "ContactList"("id"), "name" TEXT NOT NULL, "phone" TEXT NOT NULL, "rawPhone" TEXT NOT NULL, "tags" TEXT NOT NULL DEFAULT '[]', "customFields" TEXT NOT NULL DEFAULT '{}', "origin" TEXT NOT NULL, "status" TEXT NOT NULL, "validationError" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "contactListId", "phone"));
CREATE TABLE IF NOT EXISTS "MessageTemplate" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "name" TEXT NOT NULL, "body" TEXT NOT NULL, "mediaUrl" TEXT, "variables" TEXT NOT NULL DEFAULT '[]', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Campaign" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "connectionId" TEXT NOT NULL REFERENCES "WhatsAppConnection"("id"), "contactListId" TEXT NOT NULL REFERENCES "ContactList"("id"), "name" TEXT NOT NULL, "message" TEXT NOT NULL, "mediaUrl" TEXT, "status" TEXT NOT NULL, "totalContacts" INTEGER NOT NULL DEFAULT 0, "totalSent" INTEGER NOT NULL DEFAULT 0, "totalDelivered" INTEGER NOT NULL DEFAULT 0, "totalFailures" INTEGER NOT NULL DEFAULT 0, "totalPending" INTEGER NOT NULL DEFAULT 0, "scheduledAt" TIMESTAMP, "startedAt" TIMESTAMP, "finishedAt" TIMESTAMP, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "CampaignContact" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL, "campaignId" TEXT NOT NULL REFERENCES "Campaign"("id"), "contactId" TEXT NOT NULL REFERENCES "Contact"("id"), "status" TEXT NOT NULL, "providerMessageId" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "campaignId", "contactId"));
CREATE TABLE IF NOT EXISTS "MessageJob" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "campaignId" TEXT NOT NULL REFERENCES "Campaign"("id"), "contactId" TEXT NOT NULL REFERENCES "Contact"("id"), "connectionId" TEXT NOT NULL REFERENCES "WhatsAppConnection"("id"), "message" TEXT NOT NULL, "mediaUrl" TEXT, "attempt" INTEGER NOT NULL DEFAULT 0, "maxAttempts" INTEGER NOT NULL DEFAULT 3, "status" TEXT NOT NULL, "scheduledAt" TIMESTAMP NOT NULL, "idempotencyKey" TEXT NOT NULL, "queueJobId" TEXT NOT NULL, "providerMessageId" TEXT, "startedAt" TIMESTAMP, "sentAt" TIMESTAMP, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "idempotencyKey"));
CREATE TABLE IF NOT EXISTS "MessageLog" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "type" TEXT NOT NULL, "campaignId" TEXT, "connectionId" TEXT, "messageJobId" TEXT, "contactId" TEXT, "message" TEXT, "status" TEXT NOT NULL, "error" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "AuditLog" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id"), "actorId" TEXT, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "payload" TEXT NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
